// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Genel ek sorular: Ekonomi ve Finans kategorisinde bankada henüz sorulmamış bilgi ve beceriler (bu kategorinin alt alanları: Temel ekonomi kavramları: arz-talep, piyasa, üretim | Para, bankacılık, enflasyon, faiz ve kişisel finans | Uluslararası ekonomi, ticaret ve ekonomi tarihi | Girişimcilik, işletme, muhasebe ve vergi temel kavramları) (kolay).
const ozEconomics5Kolay = <(String, String, List<String>, String)>[
  ('Bir ülkede çalışma çağındaki nüfus 50 milyon, işgücü 30 milyon ve işsiz sayısı 3 milyondur. İşsizlik oranı yüzde kaçtır?', '10', ['6', '9', '7,5'], 'İşsizlik oranı işsizlerin işgücüne oranıdır: 3/30 = 0,10, yani yüzde 10. Çalışma çağındaki nüfusa bölmek yanlış olur.'),
  ('Üniversiteden yeni mezun olan Elif, kendisine uygun bir iş bulana kadar üç ay boyunca iş başvurusu yapıp görüşmelere katılıyor. Bu süredeki işsizliği hangi türe girer?', 'Friksiyonel (arızi) işsizlik', ['Yapısal işsizlik', 'Konjonktürel (döngüsel) işsizlik', 'Gizli işsizlik'], 'İşçilerle uygun işlerin birbirini bulması zaman aldığı için ortaya çıkan kısa süreli işsizliğe friksiyonel işsizlik denir.'),
  ('Bir bölgede dokuma fabrikalarının otomasyona geçmesiyle eski dokumacıların becerileri artık hiçbir işverence aranmıyor. Bu kişilerin işsizliği en iyi hangi kavramla açıklanır?', 'Yapısal işsizlik', ['Mevsimlik işsizlik', 'Friksiyonel işsizlik', 'Gönüllü işsizlik'], 'İşçilerin sahip olduğu becerilerle ekonominin talep ettiği beceriler arasındaki uyumsuzluktan doğan kalıcı işsizlik yapısal işsizliktir.'),
  ('Bir sahil kasabasında otellerde çalışan garsonların her yıl kasım ile nisan arasında işsiz kalması hangi işsizlik türüne örnektir?', 'Mevsimlik işsizlik', ['Yapısal işsizlik', 'Teknolojik işsizlik', 'Konjonktürel işsizlik'], 'Üretim ya da talebin yıl içindeki düzenli dalgalanmalarına bağlı işsizlik mevsimlik işsizliktir; turizm ve tarımda sık görülür.'),
  ('Bir resesyon döneminde toplam talebin düşmesiyle firmaların üretimi kısıp işçi çıkarması sonucu artan işsizliğe ne ad verilir?', 'Konjonktürel (döngüsel) işsizlik', ['Friksiyonel işsizlik', 'Yapısal işsizlik', 'Doğal işsizlik'], 'İş çevrimlerine, yani ekonominin daralma dönemlerine bağlı olarak artan işsizlik konjonktürel işsizliktir.'),
  ('İktisatta doğal işsizlik oranı genellikle hangi işsizlik türlerinin toplamı olarak tanımlanır?', 'Friksiyonel ve yapısal işsizlik', ['Konjonktürel ve mevsimlik işsizlik', 'Yalnız konjonktürel işsizlik', 'Gizli ve konjonktürel işsizlik'], 'Ekonomi tam kapasiteyle çalışırken bile var olan friksiyonel ve yapısal işsizlik doğal işsizliği oluşturur; konjonktürel işsizlik sıfırdır.'),
  ('Aynı miktarda ürün elde edilmesini sağlayan farklı emek-sermaye bileşimlerini gösteren eğriye ne ad verilir?', 'Eş ürün eğrisi (izokuant)', ['Kayıtsızlık eğrisi', 'Üretim olanakları eğrisi', 'Eş maliyet doğrusu (izomaliyet)'], 'İzokuant üzerindeki her nokta aynı üretim düzeyini verir; tüketici kuramındaki kayıtsızlık eğrisinin üretimdeki karşılığıdır.'),
  ('Firmanın belirli bir toplam harcamayla satın alabileceği tüm emek ve sermaye bileşimlerini gösteren doğruya ne ad verilir?', 'Eş maliyet doğrusu', ['Eş ürün eğrisi', 'Bütçe doğrusu', 'Toplam maliyet eğrisi'], 'Eş maliyet doğrusunun eğimi girdi fiyatlarının oranına eşittir; en düşük maliyetli bileşim bu doğrunun izokuanta teğet olduğu noktadadır.'),
  ('Bir oyuncunun kazancının tam olarak diğer oyuncunun kaybına eşit olduğu, satranç ya da tek maçlık bir bahis gibi oyunlara oyun teorisinde ne ad verilir?', 'Sıfır toplamlı oyun', ['Koordinasyon oyunu', 'Tekrarlı oyun', 'Pozitif toplamlı oyun'], 'Sıfır toplamlı oyunlarda oyuncuların kazanç ve kayıplarının toplamı her sonuçta sıfırdır; bir tarafın kazancı ötekinin kaybıdır.'),
  ('Tekrarlı bir mahkûm ikilemi turnuvasında, ilk turda iş birliği yapıp sonra rakibin bir önceki turda yaptığını aynen tekrarlayan strateji hangi adla bilinir?', 'Kısasa kısas (tit-for-tat)', ['Sonsuz kin (grim trigger)', 'Her turda ihanet etme stratejisi', 'Rastgele strateji'], 'Robert Axelrod\'un düzenlediği bilgisayar turnuvalarında Anatol Rapoport\'un önerdiği kısasa kısas stratejisi en başarılı sonuçlardan birini elde etmiştir.'),
  ('İki sürücünün birbirine doğru hızla ilerlediği ve önce yoldan çıkanın \'korkak\' sayıldığı, ikisi de geri adım atmazsa en kötü sonucun gerçekleştiği oyuna ne ad verilir?', 'Tavuk oyunu', ['Mahkûm ikilemi', 'Geyik avı oyunu', 'Ültimatom oyunu'], 'Tavuk oyununda iki saf Nash dengesi vardır: oyunculardan biri yoldan çıkar, öteki çıkmaz. İkisinin de çıkmaması felaketle sonuçlanır.'),
  ('Ülkelerin gelir düzeyi yükseldikçe kamu harcamalarının milli gelire oranının da artma eğiliminde olduğunu ileri süren görüş kimin adıyla anılır?', 'Adolph Wagner', ['Arthur Laffer', 'David Ricardo', 'Alfred Marshall'], 'Wagner yasası, sanayileşme ve kentleşmeyle kamu hizmetlerine olan talebin gelirden hızlı arttığını öne sürer.'),
  ('Gelir dağılımını göstermek için, nüfusun en yoksuldan en zengine sıralanan birikimli yüzdelerine karşılık aldıkları birikimli gelir yüzdelerini gösteren eğriye ne ad verilir?', 'Lorenz eğrisi', ['Laffer eğrisi', 'Engel eğrisi', 'Phillips eğrisi'], 'Lorenz eğrisi tam eşitlik doğrusuna ne kadar yakınsa gelir dağılımı o kadar eşittir; eğri bu doğrudan uzaklaştıkça eşitsizlik artar.'),
  ('Gini katsayısı 0 ile 1 arasında değer alır. Bir ülkede Gini katsayısının 0,30\'dan 0,45\'e çıkması ne anlama gelir?', 'Gelir dağılımındaki eşitsizlik artmıştır', ['Gelir dağılımı daha eşit hâle gelmiştir', 'Kişi başına gelir yüzde 15 artmıştır', 'Yoksulluk sınırının altındaki nüfus yarıya inmiştir'], 'Gini katsayısı sıfırda tam eşitliği, birde tam eşitsizliği gösterir; değerin büyümesi eşitsizliğin arttığını anlatır.'),
  ('Gayrisafi yurt içi hasıladan sabit sermaye tüketimi (amortisman) düşüldüğünde elde edilen büyüklüğe ne ad verilir?', 'Net yurt içi hasıla', ['Gayrisafi milli hasıla', 'Kullanılabilir gelir', 'Kişisel gelir'], 'Safi (net) yurt içi hasıla, üretim sırasında aşınan sermayenin değeri çıkarıldıktan sonra kalan nettir.'),
  ('İki tarafın belirli bir süre boyunca, örneğin birinin sabit faiz diğerinin değişken faiz ödemelerini karşılıklı olarak değiş tokuş etmeyi kabul ettiği türev sözleşmeye ne ad verilir?', 'Swap (takas) sözleşmesi', ['Alım opsiyonu sözleşmesi', 'Repo sözleşmesi', 'Varant'], 'Faiz swapında taraflar anapara değil faiz akımlarını değiş tokuş eder; döviz swaplarında farklı para birimleri takas edilir.'),
  ('Opsiyon alıcısının, opsiyonun sağladığı hak karşılığında satıcıya peşin olarak ödediği bedele ne ad verilir?', 'Opsiyon primi', ['Kullanım fiyatı', 'Başlangıç teminatı', 'Kupon ödemesi'], 'Opsiyon primi hakkın fiyatıdır; kullanım fiyatı ise hak kullanıldığında dayanak varlığın alınıp satılacağı fiyattır.'),
  ('İhraççısına, tahvili vadesinden önce belirli bir fiyattan geri ödeyip itfa etme hakkı tanıyan tahvillere ne ad verilir?', 'Geri çağrılabilir tahvil', ['Dönüştürülebilir tahvil', 'İskontolu bono', 'Süresiz (konsol) tahvil'], 'Faizler düştüğünde ihraççı bu tahvilleri geri çağırıp daha ucuza borçlanabilir; bu risk karşılığında yatırımcılar daha yüksek getiri ister.'),
  ('Sahibine, belirli koşullarda tahvilini ihraççı şirketin hisse senedine çevirme hakkı veren borçlanma aracına ne ad verilir?', 'Paya dönüştürülebilir tahvil', ['Geri çağrılabilir tahvil', 'Gelir ortaklığı senedi', 'Hazine bonosu'], 'Dönüştürülebilir tahvil yatırımcıya hisse fiyatı yükselirse ortak olma seçeneği sunar; bu nedenle kupon faizi genellikle daha düşüktür.'),
  ('Bankaların ağır bir ekonomik senaryo, örneğin derin bir resesyon ve sert kur artışı altında sermayelerinin yeterli kalıp kalmayacağını sınayan denetim yöntemine ne ad verilir?', 'Stres testi', ['Bağımsız denetim', 'Kredi skorlaması', 'Reeskont işlemi'], 'Stres testleri olumsuz senaryolarda bankaların kayıplarını ve sermaye yeterliliğini öngörmek için düzenleyicilerce uygulanır.'),
  ('Net bugünkü değer yöntemine göre birbirinden bağımsız bir yatırım projesi hangi durumda kabul edilmelidir?', 'Net bugünkü değeri sıfırdan büyükse', ['Toplam nakit girişleri yatırımdan küçükse', 'İç verim oranı iskonto oranından küçükse', 'Geri ödeme süresi proje ömründen uzunsa'], 'Pozitif net bugünkü değer, projenin sermayenin maliyetinin üzerinde getiri sağlayarak firmanın değerini artırdığını gösterir.'),
  ('Bir yatırım projesinin net bugünkü değerini sıfıra eşitleyen iskonto oranına ne ad verilir?', 'İç verim oranı', ['Sermaye maliyeti', 'Kupon oranı', 'Muhasebe kârlılık oranı'], 'İç verim oranı projenin kendi getirisidir; bu oran sermaye maliyetinden yüksekse proje genellikle kabul edilir.'),
  ('Maliyeti 60.000 lira olan bir güneş paneli sistemi her yıl 15.000 liralık elektrik tasarrufu sağlıyor. Basit geri ödeme süresi kaç yıldır?', '4', ['3', '5', '4,5'], 'Geri ödeme süresi yatırımın nakit girişleriyle karşılanma süresidir: 60.000 / 15.000 = 4 yıl.'),
  ('Piyasa değeri 3 milyar lira, öz kaynaklarının defter değeri 1,5 milyar lira olan bir şirketin piyasa değeri/defter değeri (PD/DD) oranı kaçtır?', '2', ['0,5', '4,5', '1,5'], 'PD/DD = piyasa değeri / öz kaynakların defter değeri = 3 / 1,5 = 2. Yatırımcılar şirkete defterdeki değerinin iki katı değer biçmektedir.'),
  ('Bir fon yöneticisinin, üstlendiği risk dikkate alındığında karşılaştırma ölçütünün üzerinde elde ettiği ek getiriye yatırım dünyasında ne ad verilir?', 'Alfa', ['Beta', 'Volatilite', 'Temettü verimi'], 'Alfa, riske göre düzeltilmiş fazla getiridir; pozitif alfa yöneticinin piyasadan daha iyi performans gösterdiğini anlatır.'),
  ('Finansal analizde sıkça kullanılan FAVÖK kısaltması neyi ifade eder?', 'Faiz, amortisman ve vergi öncesi kâr', ['Faaliyet artı vergi öncesi kazanç', 'Finansman ve varlık ölçüm kârı', 'Faiz ve vergi sonrası öz kaynak kârı'], 'FAVÖK (İngilizcede EBITDA), şirketin faaliyetlerinden finansman yapısı, vergi ve amortisman etkileri dışarıda bırakılarak elde ettiği kârı gösterir.'),
  ('Net kârı 40.000 lira, toplam varlıkları 500.000 lira olan bir işletmenin aktif kârlılığı (ROA) yüzde kaçtır?', '8', ['12,5', '40', '4'], 'Aktif kârlılığı net kârın toplam varlıklara oranıdır: 40.000 / 500.000 = 0,08, yani yüzde 8.'),
  ('IS-LM modelinde IS eğrisi hangi piyasanın dengesini sağlayan faiz-gelir bileşimlerini gösterir?', 'Mal ve hizmet piyasasının', ['Para piyasasının', 'Emek piyasasının', 'Döviz ve sermaye piyasasının'], 'IS eğrisi yatırımın tasarrufa (mal piyasasında toplam harcamanın üretime) eşit olduğu noktaları, LM eğrisi ise para talebinin para arzına eşit olduğu noktaları gösterir.'),
  ('Yatırımların gelirin düzeyine değil, gelirdeki değişmeye bağlı olduğunu; satışlar hızla arttığında yatırımların daha da hızlı artacağını söyleyen ilke hangisidir?', 'Hızlandıran ilkesi', ['Çarpan ilkesi', 'Azalan verimler ilkesi', 'Karşılaştırmalı üstünlük ilkesi'], 'Hızlandıran ilkesine göre talepteki artışı karşılamak için gereken sermaye stoku artışı yatırımları belirler; bu nedenle yatırımlar gelirden daha oynaktır.'),
  ('Bilinen ilk madenî paraların, altın ve gümüş alaşımı olan elektrumdan, MÖ 7. yüzyılda Anadolu\'da basıldığı kabul edilir. Bu paraları basan krallık hangisidir?', 'Lidya', ['Frigya', 'Urartu', 'Hitit'], 'Batı Anadolu\'daki Lidya Krallığı, başkenti Sardes\'te elektrumdan damgalı sikkeler basarak madenî paranın kullanımını başlatmıştır.'),
  ('14. yüzyılın sonunda Floransa\'da kurulan ve Avrupa\'nın pek çok kentinde şubesi bulunan, Papalığın da bankacılığını yapan ünlü banka hangi aileye aittir?', 'Medici', ['Rothschild', 'Fugger', 'Borgia'], 'Medici Bankası 1397\'de Giovanni di Bicci de\' Medici tarafından kurulmuş; aile, bankacılıktan elde ettiği servetle Rönesans sanatının hamisi olmuştur.'),
  ('ABD\'de tekelleşmeyi ve rekabeti kısıtlayan anlaşmaları yasaklayan ilk federal yasa olan 1890 tarihli düzenleme hangisidir?', 'Sherman Antitröst Yasası', ['Glass-Steagall Yasası', 'Smoot-Hawley Tarife Yasası', 'Sosyal Güvenlik Yasası'], 'Sherman Yasası 1911\'de Standard Oil\'in parçalara bölünmesi gibi tarihî davaların dayanağı olmuştur.'),
  ('19 Ekim 1987\'de Dow Jones endeksinin bir günde yaklaşık yüzde 22,6 değer kaybettiği borsa çöküşü hangi adla bilinir?', 'Kara Pazartesi', ['Kara Perşembe', 'Kara Çarşamba', 'Kara Salı'], 'Kara Pazartesi, Dow Jones\'un tek günde yüzde olarak yaşadığı en büyük düşüştür; bilgisayarlı program alım-satımlarının çöküşü hızlandırdığı düşünülmüştür.'),
  ('2008 küresel krizinde üç büyük bankası kısa sürede çöken ve bankacılık sektörü ekonomisinin birkaç katına ulaşmış olan Kuzey Atlantik ada ülkesi hangisidir?', 'İzlanda', ['İrlanda', 'Norveç', 'Danimarka'], 'Kaupthing, Landsbanki ve Glitnir Ekim 2008\'de devletleştirildi; İzlanda kronası sert değer kaybetti ve ülke IMF\'ye başvurdu.'),
  ('Sanayi Devrimi sırasında İngiltere\'de 1811-1816 yılları arasında işlerini kaybetme korkusuyla dokuma makinelerini kıran işçilere ne ad verilir?', 'Ludditler', ['Çartistler', 'Fabianlar', 'Levellerlar'], 'Ludditler makineleşmenin işsizlik yarattığını düşünerek fabrikalardaki dokuma tezgâhlarını tahrip etmiştir; adları bugün teknoloji karşıtları için de kullanılır.'),
  ('Osmanlı Devleti\'nde çiftçilere düşük faizli kredi sağlamak amacıyla Mithat Paşa\'nın Niş valiliği sırasında kurduğu ve Ziraat Bankası\'nın temeli sayılan kurumlar hangi adla bilinir?', 'Memleket Sandıkları', ['Avarız Sandıkları', 'Esnaf Loncaları', 'Mukataa Kalemleri'], 'Mithat Paşa 1863\'te Niş valisiyken ilk Memleket Sandığı\'nı Pirot\'ta kurmuş; bu sandıklar 1888\'de Ziraat Bankası\'na dönüştürülmüştür.'),
  ('Osmanlı\'da sikkelerin içindeki altın ya da gümüş oranının düşürülerek aynı nominal değerde daha fazla para basılmasına ne ad verilirdi?', 'Tağşiş', ['İltizam', 'Müsadere', 'Narh'], 'Tağşiş, devletin hazine açığını kapatmak için başvurduğu bir yöntemdi; paranın değerini düşürerek fiyat artışlarına ve halkın tepkisine yol açardı.'),
  ('Türkiye İş Bankası\'nın kuruluşu ile ilgili aşağıdakilerden hangisi doğrudur?', '1924\'te Mustafa Kemal\'in öncülüğünde, Celal Bayar\'ın genel müdürlüğünde kuruldu', ['1863\'te Mithat Paşa tarafından çiftçilere tarım kredisi vermek için kuruldu', '1930\'da merkez bankası işlevi görmek üzere özel bir yasayla kuruldu', '1933\'te devletçilik döneminde dokuma fabrikalarını yönetmek için kuruldu'], 'İş Bankası 26 Ağustos 1924\'te kurulan ilk ulusal özel bankalardan biridir; ilk genel müdürü Celal Bayar\'dır.'),
  ('Türkiye\'de 1935\'te maden arama, işletme ve enerji yatırımlarını finanse etmek amacıyla kurulan kamu kuruluşu hangisidir?', 'Etibank', ['Sümerbank', 'Emlak Bankası', 'Vakıflar Bankası'], 'Etibank madencilik ve elektrik alanlarında yatırım yapmış; adını Anadolu\'daki eski Hitit (Eti) uygarlığından almıştır.'),
  ('İkinci Dünya Savaşı yıllarında, 1942\'de savaş zenginlerinden ve servet sahiplerinden bir defaya mahsus alınmak üzere çıkarılan ve gayrimüslim yurttaşlara ağır biçimde uygulandığı için eleştirilen vergi hangisidir?', 'Varlık Vergisi', ['Toprak Mahsulleri Vergisi', 'Kazanç Vergisi', 'Muamele Vergisi'], 'Varlık Vergisi Kasım 1942\'de yürürlüğe girmiş; ödeyemeyenler mallarına el konulması ve çalışma kamplarına gönderilme gibi yaptırımlarla karşılaşmıştır.'),
  ('14. yüzyılda yazdığı Mukaddime\'de vergi oranları düşükken vergi gelirinin yüksek, oranlar arttıkça üretim azaldığı için gelirin düştüğünü anlatan düşünür kimdir?', 'İbn Haldun', ['Farabi', 'Nizamülmülk', 'Kâtip Çelebi'], 'İbn Haldun\'un bu gözlemi yüzyıllar sonra Arthur Laffer\'in vergi eğrisine esin kaynağı olarak anılmıştır.'),
  ('Thomas Piketty\'nin \'Yirmi Birinci Yüzyılda Kapital\' adlı eserinde servet eşitsizliğinin artmasını açıklamak için kullandığı temel eşitsizlik hangisidir?', 'r > g (sermaye getirisi büyüme hızından büyüktür)', ['MV = PY (para miktarı eşitliği)', 'S = I (tasarruf yatırıma eşittir)', 'P = MC (fiyat marjinal maliyete eşittir)'], 'Piketty\'ye göre sermayenin getiri oranı (r) ekonominin büyüme hızını (g) aştığında, miras kalan servet emek gelirlerinden hızlı büyür ve eşitsizlik derinleşir.'),
  ('Ortak kaynakların yerel topluluklarca kendi koydukları kurallarla, devlet ya da özelleştirmeye gerek kalmadan sürdürülebilir biçimde yönetilebileceğini gösteren ve 2009 Nobel İktisat Ödülü\'nü alan ilk kadın kimdir?', 'Elinor Ostrom', ['Joan Robinson', 'Esther Duflo', 'Claudia Goldin'], 'Ostrom, İsviçre meralarından Nepal sulama sistemlerine kadar pek çok örnekte \'müştereklerin trajedisi\'nin kaçınılmaz olmadığını göstermiştir.'),
  ('Kalkınmayı gelir artışından çok insanların değer verdikleri yaşamı sürebilme özgürlüklerinin, yani \'yapabilirliklerinin\' genişlemesi olarak tanımlayan iktisatçı kimdir?', 'Amartya Sen', ['Arthur Lewis', 'Walt Rostow', 'Gunnar Myrdal'], 'Amartya Sen\'in yapabilirlik yaklaşımı İnsani Gelişme Endeksi\'nin kavramsal temelini oluşturmuştur; Sen 1998\'de Nobel İktisat Ödülü\'nü almıştır.'),
  ('Bir ülkede kişi başı gelir uzun yıllar boyunca belirgin biçimde arttığı hâlde ortalama mutluluk düzeyinin pek değişmemesi gözlemi hangi adla anılır?', 'Easterlin paradoksu', ['Leontief paradoksu', 'Tasarruf paradoksu', 'Değer paradoksu'], 'Richard Easterlin\'in 1974\'teki gözlemi, belirli bir gelir düzeyinden sonra mutluluğun mutlak gelirden çok göreli gelire bağlı olabileceğini düşündürmüştür.'),
  ('Bir yatırımcının faizi düşük bir para biriminde borçlanıp elde ettiği fonu faizi yüksek bir para biriminde değerlendirerek faiz farkından kazanç sağlamaya çalışmasına ne ad verilir?', 'Taşıma ticareti (carry trade)', ['Arbitraj işlemi', 'Açığa satış (short selling)', 'Sterilizasyon'], 'Taşıma ticaretinde kazanç faiz farkından gelir; ancak yüksek faizli para birimi sert değer kaybederse yatırımcı büyük zarara uğrayabilir.'),
  ('Yüksek getiri arayışıyla kısa vadeli olarak bir ülkeye gelen ve küçük bir olumsuz gelişmede hızla ülkeyi terk edebilen portföy yatırımlarına halk arasında ne ad verilir?', 'Sıcak para', ['Doğrudan yabancı yatırım', 'İşçi dövizi', 'Resmî kalkınma yardımı'], 'Sıcak para hisse, tahvil ve mevduat gibi likit varlıklara yönelir; ani çıkışı kurda ve faizde sert dalgalanmalara yol açabilir.'),
  ('Bir ülkede bütçe açığı ile cari işlemler açığının aynı anda görülmesine ne ad verilir?', 'İkiz açıklar', ['Çifte vergilendirme', 'Ödemeler dengesi fazlası', 'Yapısal fazla'], 'Milli gelir özdeşliğine göre kamu kesiminin tasarruf açığı özel kesimin tasarruf fazlasıyla karşılanmazsa dış tasarrufa, yani cari açığa ihtiyaç doğar.'),
  ('1 avro = 1,20 dolar ve 1 dolar = 35 lira ise çapraz kur hesabına göre 1 avro kaç liradır?', '42', ['29,17', '36,20', '43,20'], 'Çapraz kur iki kurun çarpılmasıyla bulunur: 1,20 × 35 = 42 lira.'),
  ('Bir ülkenin merkez bankası ulusal parasını tek bir yabancı paraya karşı küçük ve önceden duyurulan adımlarla düzenli biçimde değer kaybettiriyorsa bu kur rejimi nasıl adlandırılır?', 'Sürünen (kaygan) çapa', ['Serbest dalgalanma', 'Para kurulu', 'Para birliği'], 'Sürünen çapada kur sabitlenmez ama önceden belirlenen hızda ayarlanır; yüksek enflasyonlu ülkelerde rekabet gücünü korumak için kullanılmıştır.'),
  ('Siyasetçilerin ve bürokratların da piyasadaki bireyler gibi kendi çıkarlarını gözettiğini varsayarak devlet kararlarını inceleyen ve James Buchanan\'ın öncülük ettiği yaklaşım hangisidir?', 'Kamu tercihi kuramı', ['Kurumsal iktisat', 'Fizyokrasi', 'Yeni Keynesyen iktisat'], 'James Buchanan 1986\'da kamu tercihi kuramına katkılarıyla Nobel İktisat Ödülü\'nü almıştır; kuram devletin de başarısız olabileceğini (hükümet başarısızlığı) vurgular.'),
  ('Düzenleyici bir kurumun zamanla kamu yararı yerine denetlediği sektörün çıkarlarını gözetmeye başlamasına ne ad verilir?', 'Düzenleyici yakalanma', ['Ahlaki tehlike', 'Ters seçim', 'Bedavacılık'], 'George Stigler\'in geliştirdiği yaklaşıma göre sektör, bilgi ve lobi gücüyle düzenleyiciyi etkiler; düzenleme sektördeki firmaları koruyan bir araca dönüşebilir.'),
  ('Batı Almanya\'da Ludwig Erhard\'ın uyguladığı, serbest piyasayı güçlü rekabet kurallarıyla ve sosyal güvenlik ağıyla birleştiren ekonomik model hangi adla anılır?', 'Sosyal piyasa ekonomisi', ['Merkezi planlı ekonomi', 'Laissez-faire kapitalizmi', 'Devlet kapitalizmi'], 'Ordoliberal düşünceye dayanan sosyal piyasa ekonomisi, savaş sonrası Almanya\'nın toparlanmasının kurumsal çerçevesini oluşturmuştur.'),
  ('Hastalık, kaza ve yaşlılık sigortalarını 1880\'lerde yasayla zorunlu kılarak devlet destekli ilk kapsamlı sosyal sigorta sistemini kuran devlet adamı kimdir?', 'Otto von Bismarck', ['Franklin D. Roosevelt', 'William Beveridge', 'Winston Churchill'], 'Bismarck 1883\'te hastalık, 1884\'te iş kazası, 1889\'da yaşlılık ve malullük sigortasını getirmiştir; amaçlarından biri sosyalist hareketin etkisini azaltmaktı.'),
  ('İngiltere\'de 1942\'de yayımlanan ve \'yoksulluk, hastalık, cehalet, sefalet ve aylaklık\' adlı beş büyük kötülükle mücadeleyi öneren, savaş sonrası refah devletinin temelini atan rapor hangisidir?', 'Beveridge Raporu', ['Keynes Planı', 'Radcliffe Komitesi Raporu', 'Marshall Raporu'], 'William Beveridge\'in raporu Ulusal Sağlık Hizmeti\'nin (NHS) kurulmasına ve kapsamlı sosyal güvenlik sistemine zemin hazırlamıştır.'),
  ('İrlanda\'da 1845-1849 yıllarında yaşanan ve yaklaşık bir milyon kişinin ölümüne, bir o kadarının da göçüne yol açan Büyük Kıtlığın doğrudan nedeni neydi?', 'Patates mahsulünü yok eden bir bitki hastalığı', ['Buğday ithalatının tamamen yasaklanması', 'Uzun süren bir iç savaş', 'Para biriminin aşırı değer kaybetmesi'], 'Phytophthora infestans adlı mantar benzeri organizmanın neden olduğu patates küfü, temel besini patates olan yoksul nüfusu açlığa sürüklemiştir.'),
  ('Kirliliğe yol açan tarafın, verdiği çevresel zararın maliyetini kendisinin karşılaması gerektiğini öngören çevre politikası ilkesi hangisidir?', 'Kirleten öder ilkesi', ['İhtiyatlılık ilkesi', 'Genellik ilkesi', 'Yararlanan öder ilkesi'], 'Kirleten öder ilkesi, dışsal maliyetlerin içselleştirilmesini amaçlar; çevre vergileri ve tazminat yükümlülükleri bu ilkeye dayanır.'),
  ('Bir ülkenin GSYH\'sinden doğal kaynakların tükenmesi ve çevresel bozulmanın maliyeti düşülerek hesaplanan büyüklüğe genel olarak ne ad verilir?', 'Yeşil GSYH', ['Reel GSYH', 'Potansiyel GSYH', 'Nominal GSMH'], 'Geleneksel GSYH ormanların kesilmesini ya da madenlerin tükenmesini gelir olarak sayar; yeşil GSYH bu doğal sermaye kaybını hesaba katmaya çalışır.'),
  ('Bir ikinci fiyat kapalı zarf açık artırmasında üç teklif 900, 750 ve 600 liradır. Kazanan kim olur ve kaç lira öder?', '900 lira teklif eden kazanır, 750 lira öder', ['900 lira teklif eden kazanır, 900 lira öder', '750 lira teklif eden kazanır, 750 lira öder', '900 lira teklif eden kazanır ve 600 lira öder'], 'Bu yöntemde en yüksek teklifi veren kazanır ama ikinci en yüksek teklif kadar öder: 750 lira.'),
  ('Bir iş uyuşmazlığında işverenin işçilerin çalışmasını engellemek amacıyla işyerini geçici olarak kapatmasına ne ad verilir?', 'Lokavt', ['Grev', 'İşten çıkarma', 'Toplu sözleşme'], 'Grev işçilerin topluca işi bırakması, lokavt ise işverenin işyerini kapatarak işçileri çalıştırmamasıdır.'),
  ('Kurye, sürücü ya da serbest tasarımcı gibi kişilerin dijital platformlar aracılığıyla iş başına ücretle, kısa süreli ve bağımsız olarak çalıştığı ekonomik yapıya ne ad verilir?', 'Gig (iş başına) ekonomisi', ['Kayıt dışı ekonomi', 'Kolektif (kooperatif) ekonomi', 'Kapalı ekonomi'], 'Gig ekonomisi esneklik sağlarken sosyal güvenlik, asgari ücret ve iş güvencesi gibi konularda yeni düzenleme tartışmalarını gündeme getirmiştir.'),
];
